// P2-4: docs/features-pending.md, made from the data: every level 1 to 3 feature marked mechanics: 'later',
// shown as text only for now, so the work of running them can be scheduled.
import type { SrdClass } from './schemas';

export function featuresPending(classes: SrdClass[]): string {
  const lines = [
    '# Features shown as text only (mechanics later)',
    '',
    'Generated by `pnpm -C packages/srd-data convert` from `packages/srd-data/data`; do not edit by hand. Each feature',
    'below has game mechanics (uses per rest, conditional bonuses, choices) that the app shows as SRD text but does',
    'not run yet. Levels 1 to 3 only.',
    '',
  ];
  let total = 0;
  for (const c of classes) {
    const rows = [
      ...c.levels.flatMap(l => l.features.map(f => ({ ...f, from: c.name }))),
      ...c.subclasses.flatMap(s => s.features.map(f => ({ ...f, from: s.name }))),
    ].filter(f => f.mechanics === 'later');
    if (!rows.length) continue;
    total += rows.length;
    lines.push(`## ${c.name}`, '', '| Level | Feature | From |', '| ----- | ------- | ---- |');
    for (const f of rows.sort((a, b) => a.level - b.level)) lines.push(`| ${f.level} | ${f.name} | ${f.from} |`);
    lines.push('');
  }
  lines.push(`${total} features in all.`, '');
  return lines.join('\n');
}
